        const type_info: std.builtin.Type = @typeInfo(Type);
        switch (type_info) {
.bool => {
return Expr{ .data = .{ .e_boolean = .{ .value = value } }, .loc = logger.Loc{  } };
},
.int => {
const f: f64 = @floatFromInt(value);
        return Expr{ .data = .{ .e_number = .{ .value = f } }, .loc = logger.Loc{  } };
},
.float => {
const f: f64 = @floatCast(value);
        return Expr{ .data = .{ .e_number = .{ .value = f } }, .loc = logger.Loc{  } };
},
.pointer => |ptr_info| {
switch (ptr_info.size) {
.one => {
switch (@typeInfo(ptr_info.child)) {
.array => {
const Slice = .{  };
        _ = .{ .Elem = ptr_info.child };
        return try toAST(allocator, Slice, value.*);
},
else => {
return try toAST(allocator, @TypeOf(value.*), value.*);
},
}
},
.slice => {
if ((ptr_info.child == u8)) {
            return Expr.init(js_ast.E.String, js_ast.E.String.init(value), logger.Loc.Empty);
        }
        const exprs = try allocator.alloc(Expr, value.len);
        for (exprs, 0..) |*ex, i| {
            ex.* = try toAST(allocator, @TypeOf(value[@as(usize, @intCast(i))]), value[@as(usize, @intCast(i))]);
        }
        return Expr.init(js_ast.E.Array, js_ast.E.Array{ .items = exprs }, logger.Loc.Empty);
},
else => {
_ = @compileError(std.fmt.comptimePrint("Unable to stringify type '{s}'", .{ @typeName(Type) }));
},
}
},
.array => |Array| {
if ((Array.child == u8)) {
            return Expr.init(js_ast.E.String, js_ast.E.String.init(value), logger.Loc.Empty);
        }
        const exprs = try allocator.alloc(Expr, value.len);
        for (exprs, 0..) |*ex, i| {
            ex.* = try toAST(allocator, @TypeOf(value[@as(usize, @intCast(i))]), value[@as(usize, @intCast(i))]);
        }
        return Expr.init(js_ast.E.Array, js_ast.E.Array{ .items = exprs }, logger.Loc.Empty);
},
.@"struct" => |Struct| {
const fields: []const std.builtin.Type.StructField = Struct.fields;
        var properties = try BabyList(js_ast.G.Property).initCapacity(allocator, fields.len);
        _ = &properties;
        inline for (fields) |field| {
            _ = properties.appendAssumeCapacity(G{ .Property = .{ .key = Expr.init(E.String, E{ .String = .{ .data = (if (comptime @typeInfo(@TypeOf(field)) == .@"enum" or @typeInfo(@TypeOf(field)) == .@"union") @tagName(field) else field.name) } }, logger.Loc.Empty), .value = try toAST(allocator, field.type, @field(value, (if (@typeInfo(@TypeOf(field)) == .@"enum" or @typeInfo(@TypeOf(field)) == .@"union") @tagName(field) else field.name))) } });
        }
        return Expr.init(js_ast.E.Object, js_ast.E.Object{ .properties = properties, .is_single_line = (properties.len <= 1) }, logger.Loc.Empty);
},
.null => {
return Expr{ .data = .{ .e_null = .{} }, .loc = logger.Loc{  } };
},
.optional => {
if (value) |_value| {
            _ = &_value;
            return try toAST(allocator, @TypeOf(_value), _value);
        } else {
            return Expr{ .data = .{ .e_null = .{} }, .loc = logger.Loc{  } };
        }
},
.@"enum" => {
_ = (blk_catch_7: { break :blk_catch_7 ((std.meta.intToEnum(Type, @intFromEnum(value))) catch |__ce_7| { _ = &__ce_7; return Expr{ .data = .{ .e_null = .{} }, .loc = logger.Loc{  } }; }); });
        return toAST(allocator, string, @as([]const u8, @tagName(value)));
},
.error_set => {
return try toAST(allocator, string, bun.asByteSlice(@errorName(value)));
},
.@"union" => |Union| {
const info = Union;
        if (info.tag_type) |UnionTagType| {
            _ = &UnionTagType;
            inline for (info.fields) |u_field| {
                if ((value == @field(UnionTagType, (if (@typeInfo(@TypeOf(u_field)) == .@"enum" or @typeInfo(@TypeOf(u_field)) == .@"union") @tagName(u_field) else u_field.name)))) {
                    const StructType = @Type(.{ .Struct = .{ .layout = .Auto, .decls = (&.{}), .is_tuple = false, .fields = (&.{ .{ .name = (if (comptime @typeInfo(@TypeOf(u_field)) == .@"enum" or @typeInfo(@TypeOf(u_field)) == .@"union") @tagName(u_field) else u_field.name), .type = @TypeOf(@field(value, (if (@typeInfo(@TypeOf(u_field)) == .@"enum" or @typeInfo(@TypeOf(u_field)) == .@"union") @tagName(u_field) else u_field.name))), .is_comptime = false, .default_value_ptr = undefined, .alignment = @alignOf(@TypeOf(@field(value, (if (@typeInfo(@TypeOf(u_field)) == .@"enum" or @typeInfo(@TypeOf(u_field)) == .@"union") @tagName(u_field) else u_field.name)))) } }) } });
                    var struct_value: StructType = undefined;
                    _ = &struct_value;
                    @field(struct_value, (if (@typeInfo(@TypeOf(u_field)) == .@"enum" or @typeInfo(@TypeOf(u_field)) == .@"union") @tagName(u_field) else u_field.name)) = value;
                    return try toAST(allocator, StructType, struct_value);
                }
            }
        } else {
            _ = @compileError(std.fmt.comptimePrint("Unable to stringify untagged union '{s}'", .{ @typeName(Type) }));
        }
},
else => {
_ = @compileError(std.fmt.comptimePrint("Unsupported type: {s} - {s}", .{ @tagName(type_info), @typeName(Type) }));
},
}
}

pub fn parse(source: *const logger.Source, log: *logger.Log, allocator: std.mem.Allocator, comptime force_utf8: bool) !Expr {
        var parser = try JSONParser.init(allocator, source, log);
        _ = &parser;
        switch (source.contents.len) {
0 => {
return Expr{ .loc = logger.Loc{ .start = 0 }, .data = empty_object_data };
},
2 => {
if ((strings.eqlComptime(source.contents[0..1], "\"\"") or strings.eqlComptime(source.contents[0..1], "''"))) {
            return Expr{ .loc = logger.Loc{ .start = 0 }, .data = empty_string_data };
        } else {
            if (strings.eqlComptime(source.contents[0..1], "{}")) {
                return Expr{ .loc = logger.Loc{ .start = 0 }, .data = empty_object_data };
            } else {
                if (strings.eqlComptime(source.contents[0..1], "[]")) {
                    return Expr{ .loc = logger.Loc{ .start = 0 }, .data = empty_array_data };
                }
            }
        }
},
else => {

},
}
        return try parser.parseExpr(false, force_utf8);
}

